import test from "node:test";
import assert from "node:assert/strict";
import { parseImportMetadata, pythonHash, pythonJson } from "../src/canonical";

// Expected output and SHA-256 are generated by CPython json.loads/json.dumps,
// including float type, code-point key order, arbitrary-size ints and __proto__.
const raw = String.raw`{"idempotency_key":"golden","source_id":"source","messages":[{"message_id":"a","role":"user","content":"hello","occurred_at":"2024-05-01T12:00:00Z"}],"metadata":{"tiny":1e-7,"whole":1.0,"large":1e20,"negative_zero":-0.0,"hugeint":9007199254740993123456789,"nested":[1e-6,1e-5,1e15,1e16,1.2345678901234567],"\ue000":1,"\ud800\udc00":2,"__proto__":{"x":1.0}}}`;
test("matches Python receipt fingerprint across JSON numeric forms and Unicode keys", async () => {
  const request = JSON.parse(raw);
  request.metadata = parseImportMetadata(raw);
  const value = { kind: "import", request };
  assert.equal(
    await pythonHash(value),
    "627de596ebf511b3ec9c911d2eb694a500f6c3123bcb6a00aed047a98b44a750",
  );
  const output = pythonJson(value);
  assert.match(output, /"whole":1\.0/);
  assert.match(output, /"tiny":1e-07/);
  assert.match(output, /"hugeint":9007199254740993123456789/);
  assert.match(output, /"__proto__":\{"x":1\.0\}/);
});
test("matching Python treats integral and floating metadata as distinct", async () => {
  const integral = parseImportMetadata('{"metadata":{"n":1}}');
  const floating = parseImportMetadata('{"metadata":{"n":1.0}}');
  assert.notEqual(await pythonHash(integral), await pythonHash(floating));
});

test("attachment dimensions retain Python strict integer semantics and precision", async () => {
  const { prepareImportBody } = await import("../src/canonical");
  const raw =
    '{"messages":[{"images":[{"width":9007199254740993123456789,"height":2,"byteSize":3}]}]}';
  const body = prepareImportBody(raw, JSON.parse(raw));
  assert.equal(
    pythonJson(body),
    '{"messages":[{"images":[{"byteSize":3,"height":2,"width":9007199254740993123456789}]}],"metadata":{}}',
  );
  for (const token of ["1.0", "1e0"]) {
    const invalid = `{"messages":[{"images":[{"width":${token},"height":2,"byteSize":3}]}]}`;
    assert.throws(() => prepareImportBody(invalid, JSON.parse(invalid)));
  }
});
